  "target_file": "src/demo_tasks.nim",
  "decision": "Ajouter un cas pour l'export CSV avec un drapeau CLI sans changer le comportement par défaut.",
  "edits": [
    {
      "insertAfter": "let cmd = if args.len > 0: args[0] else: \"list\"",
      "newText": "if cmd == \"export-csv\":\n      echo formatCSV(loadTasks())\n      quit()"
    },
    {
      "insertAfter": "quit(2)",
      "newText": "\nproc formatCSV*(tasks: openArray[Task]): string =\n  var lines: seq[string] = @[]\n  for t in tasks:\n    lines.add(\"\\\"\" & t.title.replace(\"\\\", \"\\\\\").replace(\",\", \"\\\"\") & \"\\\"\")\n  lines.join(\"\\n\")"
    }
  ]
}

